import{_ as f,a0 as s,w as p,s as o,ao as d,I as l,x as i,a1 as a,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何用四个简单的步骤加速 LibreOffice | LCTT x X-CMD","titleTemplate":false,"description":"如何用四个简单的步骤加速 LibreOffice | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用四个简单的步骤加速 LibreOffice | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用四个简单的步骤加速 LibreOffice | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160914 How to Speed Up LibreOffice with 4 Simple Steps","title":"如何用四个简单的步骤加速 LibreOffice","tag":"201609","desc":""},"relativePath":"201609/20160914 How to Speed Up LibreOffice with 4 Simple Steps.md","filePath":"[post].md"}'),n={name:"201609/20160914 How to Speed Up LibreOffice with 4 Simple Steps.md"};function c(b,e,m,h,u,L){const t=s("Link");return p(),o("div",null,[e[13]||(e[13]=d('<h1 id="如何用四个简单的步骤加速-libreoffice" tabindex="-1">如何用四个简单的步骤加速 LibreOffice <a class="header-anchor" href="#如何用四个简单的步骤加速-libreoffice" aria-label="Permalink to “如何用四个简单的步骤加速 LibreOffice”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/08/speed-up-libreoffice-featured-2.jpg" alt=""></p><p>对于许多许多开源软件的粉丝和支持者来说，LibreOffice 是 Microsoft Office 最好的替代品，在最近的一些发布版本中可以看到它明显有了巨大的改进。然而，初始启动的体验仍然距离期望有所距离。有一些方法可以缩短 LibreOffice 的启动时间并改善它的整体性能。</p><p>在下面的段落里，我将会展示一些实用性的步骤，你可以通过它们来改善 LibreOffice 的加载时间和响应能力。</p><h3 id="_1-增加每个对象和图像缓存的内存占用" tabindex="-1">1. 增加每个对象和图像缓存的内存占用 <a class="header-anchor" href="#_1-增加每个对象和图像缓存的内存占用" aria-label="Permalink to “1. 增加每个对象和图像缓存的内存占用”">​</a></h3><p>这将可以通过分配更多的内存资源给图像缓存和对象来加快程序的加载时间。</p><ol><li>启动 LibreOffice Writer (或者 Calc)。</li><li>点击菜单栏上的 “工具 -&gt; 选项” 或者按键盘上的快捷键“Alt + F12”。</li><li>点击 LibreOffice 下面的“内存”然后增加“用于 LibreOffice” 到 128MB。</li><li>同样的增加“每个对象的内存占用”到 20MB。</li><li>点击确定来保存你的修改。</li></ol><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/08/speed-up-libreoffice-step-1.png" alt=""></p><p>注意：你可以根据自己机器的性能把数值设置得比建议值的高一些或低一些。最好通过亲自体验来看看什么值能够让机器达到最佳性能。</p><h3 id="_2-启用-libreoffice-的快速启动器-quickstarter" tabindex="-1">2.启用 LibreOffice 的快速启动器（QuickStarter） <a class="header-anchor" href="#_2-启用-libreoffice-的快速启动器-quickstarter" aria-label="Permalink to “2.启用 LibreOffice 的快速启动器（QuickStarter）”">​</a></h3><p>如果你的机器上有足够大的内存，比如 4GB 或者更大，你可以启用“系统托盘快速启动器”，从而让 LibreOffice 的一部分保持在内存中，在打开新文件时能够快速反应。</p><p>在启用这个选择以后，你会清楚的看到在打开新文件时它的性能有了很大的提高。</p><ol><li>通过点击“工具 -&gt; 选项”来打开选项对话框。</li><li>在 “LibreOffice” 下面的侧边栏选择“内存”。</li><li>勾选“启用系统托盘快速启动器”复选框。</li><li>点击“确定”来保存修改。</li></ol><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/08/speed-up-libreoffice-2.png" alt=""></p><p>一旦这个选项启用以后，你将会在你的系统托盘看到 LibreOffice 图标，以及可以打开任何类型的文件的选项。</p><h3 id="_3-禁用-java-运行环境" tabindex="-1">3. 禁用 Java 运行环境 <a class="header-anchor" href="#_3-禁用-java-运行环境" aria-label="Permalink to “3. 禁用 Java 运行环境”">​</a></h3><p>另一个加快 LibreOffice 加载时间和响应能力的简单方法是禁用 Java。</p><ol><li>同时按下“Alt + F12”打开选项对话框。</li><li>在侧边栏里，选择“Libreoffice”，然后选择“高级”。</li><li>取消勾选“使用 Java 运行环境”选项。</li><li>点击“确定”来关闭对话框。</li></ol><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/08/speed-up-libreoffice-3.png" alt=""></p><p>如果你只使用 Writer 和 Calc，那么关闭 Java 不会影响你正常使用，但如果你需要使用 LibreOffice Base 和一些其他的特性，那么你可能需要重新启用它。在那种情况，将会弹出一个框询问你是否希望再次打开它。</p><h3 id="_4-减少使用撤销步骤" tabindex="-1">4. 减少使用撤销步骤 <a class="header-anchor" href="#_4-减少使用撤销步骤" aria-label="Permalink to “4. 减少使用撤销步骤”">​</a></h3><p>默认情况下，LibreOffice 允许你撤销一个文件的多达 100 个改变。绝大多数用户不需要这么多，所以在内存中保留这么多撤销步骤是对资源的巨大浪费。</p><p>我建议减少撤销步骤到 20 次以下来为其他东西释放内存，但是这个部分需要根据你自己的需求来确定。</p><ol><li>通过点击 “工具 -&gt; 选项”来打开选项对话框。</li><li>在 “LibreOffice” 下面的侧边栏，选择“内存”。</li><li>在“撤销”下面把步骤数目改成最适合你的值。</li><li>点击“确定”来保存修改。</li></ol><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/08/speed-up-libreoffice-5.png" alt=""></p><p>假如你这些技巧为加速你的 LibreOffice 套件的加载时间提供了帮助，请在评论里告诉我们。同样，请分享你知道的任何其他技巧来给其他人带来帮助。</p><hr>',27)),l("p",null,[e[1]||(e[1]=i("via: ",-1)),a(t,{href:"https://www.maketecheasier.com/speed-up-libreoffice/"},{default:r(()=>[...e[0]||(e[0]=[i("https://www.maketecheasier.com/speed-up-libreoffice/",-1)])]),_:1})]),l("p",null,[e[5]||(e[5]=i("作者：",-1)),a(t,{href:"https://www.maketecheasier.com/author/ayoisaiah/"},{default:r(()=>[...e[2]||(e[2]=[i("Ayo Isaiah",-1)])]),_:1}),e[6]||(e[6]=i(" 译者：",-1)),a(t,{href:"https://github.com/ucasFL"},{default:r(()=>[...e[3]||(e[3]=[i("ucasFL",-1)])]),_:1}),e[7]||(e[7]=i(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),l("p",null,[e[10]||(e[10]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[i("Linux中国",-1)])]),_:1}),e[12]||(e[12]=i(" 荣誉推出",-1))])])}const T=f(n,[["render",c]]);export{x as __pageData,T as default};
